begin;
create extension if not exists pgtap with schema extensions;
select plan(31);
select has_table('public', 'audit_export_jobs', 'audit export jobs exist');
select has_column('public', 'audit_export_jobs', 'content_sha256', 'export stores canonical hash');
select function_returns('public', 'create_approved_audit_export_job', array['uuid'], 'jsonb', 'approved export job RPC signature');
select ok((select p.prosecdef from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='create_approved_audit_export_job'), 'export job is security definer');
select ok(has_function_privilege('authenticated', 'public.create_approved_audit_export_job(uuid)', 'EXECUTE'), 'authenticated can apply approved export');
select ok(not has_function_privilege('anon', 'public.create_approved_audit_export_job(uuid)', 'EXECUTE'), 'anon cannot apply export');
select ok(not has_function_privilege('service_role', 'public.create_approved_audit_export_job(uuid)', 'EXECUTE'), 'service role cannot call operator export directly');
select ok((select pg_get_functiondef('public.create_approved_audit_export_job(uuid)'::regprocedure) like '%request_row.status <> ''approved''%'), 'only approved export requests create jobs');
select ok((select pg_get_functiondef('public.create_approved_audit_export_job(uuid)'::regprocedure) like '%approval_request_id%'), 'export job is idempotently bound to approval');
select ok((select pg_get_functiondef('public.create_approved_audit_export_job(uuid)'::regprocedure) like '%31 days%'), 'export window is bounded');
select ok((select pg_get_functiondef('public.create_approved_audit_export_job(uuid)'::regprocedure) like '%audit-export-applied:%'), 'export apply uses domain-separated audit key');
select ok((select pg_get_functiondef('public.create_approved_audit_export_job(uuid)'::regprocedure) like '%audit.export.workspace.applied%'), 'workspace export audit append is allowed');
select ok((select pg_get_functiondef('public.create_approved_audit_export_job(uuid)'::regprocedure) like '%audit.export.global.applied%'), 'global export audit append is allowed');
select ok((select pg_get_constraintdef(oid) from pg_constraint where conrelid='public.audit_export_jobs'::regclass and conname='audit_export_jobs_status_check') like '%succeeded%'), 'succeeded jobs require lifecycle status');
select function_returns('public', 'complete_audit_export_job', array['uuid','text','text','integer','bigint'], 'jsonb', 'export completion RPC signature');
select function_returns('public', 'get_audit_export_download', array['uuid'], 'jsonb', 'export download RPC signature');
select function_returns('public', 'expire_audit_export_jobs', array['timestamptz'], 'jsonb', 'export expiry RPC signature');
select ok((select pg_get_functiondef('public.complete_audit_export_job(uuid,text,text,integer,bigint)'::regprocedure) like '%p_row_count < 0%'), 'completion rejects negative counts');
select ok((select pg_get_functiondef('public.complete_audit_export_job(uuid,text,text,integer,bigint)'::regprocedure) like '%p_storage_path <>%'), 'completion validates exact private storage path');
select ok((select pg_get_functiondef('public.get_audit_export_download(uuid)'::regprocedure) like '%expires_at <= statement_timestamp()%'), 'download rejects expired jobs');
select ok((select pg_get_functiondef('public.get_audit_export_download(uuid)'::regprocedure) like '%audit.export.request%'), 'download rechecks export permission');
select ok((select pg_get_functiondef('public.expire_audit_export_jobs(timestamptz)'::regprocedure) like '%status = ''expired''%'), 'expiry boundary marks jobs expired');
select ok((select pg_get_constraintdef(oid) from pg_constraint where conrelid='public.platform_audit_events'::regclass and conname='platform_audit_events_action_check') like '%support.session.started%' and (select pg_get_constraintdef(oid) from pg_constraint where conrelid='public.platform_audit_events'::regclass and conname='platform_audit_events_action_check') like '%support.session.revoked%', 'support session audit actions remain allowed');
select function_returns('public', 'claim_audit_export_job', array['uuid'], 'jsonb', 'export claim RPC signature');
select function_returns('public', 'list_audit_export_rows', array['uuid'], 'jsonb', 'safe export rows RPC signature');
select ok((select pg_get_functiondef('public.claim_audit_export_job(uuid)'::regprocedure) like '%AUDIT_EXPORT_ALREADY_RUNNING%'), 'duplicate executors are blocked');
select function_returns('public', 'list_operator_audit_export_jobs', array['integer'], 'jsonb', 'safe export job list RPC signature');
select ok((select pg_get_functiondef('public.list_operator_audit_export_jobs(integer)'::regprocedure) not like '%storage_path%' and (select pg_get_functiondef('public.list_operator_audit_export_jobs(integer)'::regprocedure) not like '%content_sha256%'), 'safe job list excludes internal storage and full hash');
select function_returns('public', 'fail_audit_export_job', array['uuid','text'], 'jsonb', 'export failure RPC signature');
select ok((select pg_get_functiondef('public.expire_audit_export_jobs(timestamptz)'::regprocedure) like '%storage_path%'), 'expiry returns cleanup object paths');
select ok((select pg_get_functiondef('public.create_approved_audit_export_job(uuid)'::regprocedure) like '%workspace_id is null%'), 'export scope invariant is enforced');
select * from finish();
rollback;
